#[derive(Debug)]
enum PortError { NotANumber(String), OutOfRange(u16) }

fn parse_port(s: &str) -> Result<u16, PortError> {
    let port: u16 = s.trim().parse().map_err(|_| PortError::NotANumber(s.into()))?;
    if port == 0 {
        return Err(PortError::OutOfRange(port));
    }
    Ok(port)
}

match parse_port(raw) {                        // exhaustive: a new variant breaks this
    Ok(port) => println!("port {port}"),
    Err(PortError::OutOfRange(port)) => eprintln!("out of range: {port}"),
    Err(e) => eprintln!("invalid: {e:?}"),
}
